import hmac
import hashlib
from typing import Optional
from app.core.config import settings

def verify_payment_signature(razorpay_order_id: str, razorpay_payment_id: str, razorpay_signature: str, key_secret: Optional[str] = None) -> bool:
    """Cryptographically verify payment signature generated by Razorpay Checkout."""
    secret = key_secret or settings.RAZORPAY_KEY_SECRET
    msg = f"{razorpay_order_id}|{razorpay_payment_id}".encode("utf-8")
    expected_sig = hmac.new(secret.encode("utf-8"), msg, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, razorpay_signature)

def verify_webhook_signature(raw_body: bytes, razorpay_signature: str, webhook_secret: Optional[str] = None) -> bool:
    """
    Cryptographically verify webhook event authenticity using raw byte stream.
    CRITICAL: Never deserialize payload before HMAC computation.
    """
    secret = webhook_secret or settings.RAZORPAY_WEBHOOK_SECRET
    expected_sig = hmac.new(secret.encode("utf-8"), raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, razorpay_signature)
